import{_ as o,o as t,c as e,a5 as c}from"./chunks/framework.BEZBAInb.js";const g=JSON.parse('{"title":"2.8 へのアップグレード","description":"","frontmatter":{"title":"2.8 へのアップグレード","order":2},"headers":[],"relativePath":"ja/latest/tutorial/upgrade-2.8.md","filePath":"ja/latest/tutorial/upgrade-2.8.md","lastUpdated":1788455378000}'),a={name:"ja/latest/tutorial/upgrade-2.8.md"};function r(n,d,i,K,_,s){return t(),e("div",null,[...d[0]||(d[0]=[c('<h1 id="_2-8-へのアップグレード" tabindex="-1">2.8 へのアップグレード <a class="header-anchor" href="#_2-8-へのアップグレード" aria-label="Permalink to &quot;2.8 へのアップグレード&quot;">​</a></h1><p>2.8 ではランタイム、コンパイラー、プラグイン構成を再設計し、公開 API 名を統一しました。事前にプロジェクトをバックアップし、旧プラグイン一式を 2.8 に置き換えてから Godot を開き直してください。</p><p>既知のプラグインパスと Autoload 名は自動移行されます。UID を持つシーンやリソース参照は通常、新しい配置へ自動的に解決されます。ユーザーの GDScript は書き換えないため、旧型名は手動で更新します。</p><table tabindex="0"><thead><tr><th>2.7.4</th><th>2.8</th></tr></thead><tbody><tr><td><code>KND_DialogueManager</code></td><td><code>KonadoDialogueManager</code></td></tr><tr><td><code>KND_Shot</code></td><td><code>KonadoShot</code></td></tr><tr><td><code>KND_SaveSystem</code></td><td><code>KonadoSaveSystem</code></td></tr><tr><td><code>KND_SaveData</code></td><td><code>KonadoSaveData</code></td></tr><tr><td><code>KND_Settings</code></td><td><code>KonadoSettings</code></td></tr><tr><td><code>KND_SettingCategory</code></td><td><code>KonadoSettingCategory</code></td></tr><tr><td><code>KND_SettingItem</code></td><td><code>KonadoSettingItem</code></td></tr><tr><td><code>KND_SettingsUIFactory</code></td><td><code>KonadoSettingsUIFactory</code></td></tr><tr><td><code>KND_AchievementManager</code></td><td><code>KonadoAchievements</code></td></tr><tr><td><code>KND_I18n</code></td><td><code>KonadoStoryLocalization</code></td></tr><tr><td><code>KND_Background</code> / <code>KND_BackgroundList</code></td><td><code>KonadoBackground</code> / <code>KonadoBackgroundList</code></td></tr><tr><td><code>KND_Character</code> / <code>KND_CharacterList</code></td><td><code>KonadoCharacter</code> / <code>KonadoCharacterList</code></td></tr><tr><td><code>KND_CharacterSceneBase</code></td><td><code>KonadoCharacterSceneBase</code></td></tr><tr><td><code>KND_CharacterTransitionFrame</code></td><td><code>KonadoCharacterTransitionFrame</code></td></tr><tr><td><code>KND_Actor</code></td><td><code>KonadoActor</code></td></tr><tr><td><code>KND_ActingInterface</code></td><td><code>KonadoStageController</code></td></tr><tr><td><code>KND_Bgm</code> / <code>KND_BgmList</code></td><td><code>KonadoBackgroundMusic</code> / <code>KonadoBackgroundMusicList</code></td></tr><tr><td><code>DialogVoice</code> / <code>DialogVoiceList</code></td><td><code>KonadoVoice</code> / <code>KonadoVoiceList</code></td></tr><tr><td><code>KND_SoundEffect</code> / <code>KND_SoundEffectList</code></td><td><code>KonadoSoundEffect</code> / <code>KonadoSoundEffectList</code></td></tr><tr><td><code>KND_AudioInterface</code></td><td><code>KonadoAudioController</code></td></tr><tr><td><code>KND_DialogueBox</code></td><td><code>KonadoDialogueBox</code></td></tr><tr><td><code>KND_Dialogue</code> / <code>KND_DialogueChoice</code></td><td>読み取り専用の <code>KonadoInstruction</code></td></tr><tr><td><code>KND_ScreenText</code></td><td><code>KonadoScreenText</code></td></tr><tr><td><code>KND_TypewriterText</code></td><td><code>KonadoTypewriterText</code></td></tr><tr><td><code>KND_Data</code></td><td><code>KonadoData</code></td></tr><tr><td><code>KND_VariableStore</code></td><td><code>KonadoVariableStore</code></td></tr><tr><td><code>KND_BackgroundSceneBase</code></td><td><code>KonadoBackgroundSceneBase</code></td></tr><tr><td><code>KND_ActorMotionLayer</code></td><td><code>KonadoActorMotionLayer</code></td></tr><tr><td><code>KonadoCamera2D</code></td><td><code>KonadoCameraMarker</code></td></tr><tr><td><code>KND_Logger</code></td><td><code>KonadoLogger</code></td></tr></tbody></table><p>文字列として保持している旧プラグインパスも更新してください。UID で正常に解決できる通常のシーン参照は変更不要です。</p><p>旧 <code>KND_CharacterStatus</code> リソースは、キャラクターシーンのステータスプロトコルと <code>status_aliases</code> に置き換わりました。<code>KND_BackgroundTransitionLayer</code> は直接生成せず、背景遷移は <code>KonadoStageController</code> に任せてください。<code>KonadoScriptsInterpreter</code> を直接使っていたツールは、<code>KonadoScriptCompiler</code> で <code>KonadoProgram</code> を生成し、<code>KonadoDialogueManager</code> で再生する構成へ移行します。</p><p><code>.ks</code> ソースは 2.8 コンパイラーで再インポートされるため、2.7 の生成済みキャッシュをコピーしないでください。2.7 のセーブデータは 2.8 では復元できず、明示的に拒否されます。2.8 では引用符なしの話者名はアクター ID です。文字ラベルとして使う場合は引用符で囲みます。</p><p>移行後は GDScript の解析エラーがないことを確認し、すべての <code>.ks</code> を再インポートして、起動、スクリプト間ジャンプ、セーブ・ロード、言語切り替えを実機で確認してください。</p>',8)])])}const l=o(a,[["render",r]]);export{g as __pageData,l as default};
